import{_ as i,C as e,o as s,c,E as o,a5 as d}from"./chunks/framework.DOB-AMqW.js";const y=JSON.parse('{"title":"Link Deck Privacy Policy","description":"Privacy Policy for Link Deck, presented within Policy Hub.","frontmatter":{"title":"Link Deck Privacy Policy","description":"Privacy Policy for Link Deck, presented within Policy Hub."},"headers":[],"relativePath":"apps/link-deck/privacy.md","filePath":"apps/link-deck/privacy.md"}'),l={name:"apps/link-deck/privacy.md"};function p(h,a,k,u,m,b){const r=e("AppBreadcrumbs"),t=e("AppSubnav"),n=e("CopyStandaloneUrl");return s(),c("div",null,[o(r,{"app-id":"link-deck",current:"Privacy Policy"}),o(t,{"app-id":"link-deck"}),o(n,{path:"/privacy/link-deck",label:"Copy Play Store URL","copied-label":"Play Store URL copied","document-name":"Link Deck privacy policy"}),a[0]||(a[0]=d('<h1 id="privacy-policy-for-link-deck" tabindex="-1">Privacy Policy for Link Deck <a class="header-anchor" href="#privacy-policy-for-link-deck" aria-label="Permalink to &quot;Privacy Policy for Link Deck&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 1, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Link Deck is an offline-first bookmark manager developed by <strong>Anand Raja</strong>. It does not require an account and does not include advertising, analytics, tracking, or developer-operated cloud sync.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information Stored on Your Device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information Stored on Your Device&quot;">​</a></h2><p>Link Deck stores the information you enter in a local SQLite database on Android or IndexedDB in a browser. This can include profiles, nested folders, bookmark titles and URLs, descriptions, notes, tags, favourites, archive and trash status, favicons, visit counts and dates, and app settings.</p><p>The developer does not receive this database. Link Deck does not use browser localStorage or sessionStorage for application data.</p><h2 id="app-lock-and-biometrics" tabindex="-1">App Lock and Biometrics <a class="header-anchor" href="#app-lock-and-biometrics" aria-label="Permalink to &quot;App Lock and Biometrics&quot;">​</a></h2><p>If you enable an application PIN, Link Deck stores a salted PBKDF2-SHA-256 verifier rather than the PIN itself. On supported Android devices, optional biometric unlock uses Android BiometricPrompt and Android Keystore. Link Deck does not receive or store biometric templates.</p><p>The PIN and biometric features control access to the app interface. They are not a replacement for Android device encryption or a secure device lock.</p><h2 id="network-requests-and-external-websites" tabindex="-1">Network Requests and External Websites <a class="header-anchor" href="#network-requests-and-external-websites" aria-label="Permalink to &quot;Network Requests and External Websites&quot;">​</a></h2><p>When a bookmark is saved, Link Deck uses Google&#39;s favicon service to display an icon for the saved website. The request includes the saved website&#39;s hostname. Google may receive that hostname and standard connection information such as the device IP address, user agent, request time, and requested resource.</p><p>Link Deck also references Google Fonts for interface symbols. Google&#39;s handling of these requests is governed by the <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google Privacy Policy</a>.</p><p>When you open a bookmark, Link Deck sends the URL to your browser. The website, browser, network provider, and any services used by that website may process information under their own privacy practices. Link Deck does not fetch page content or send bookmark notes, tags, folders, or profiles to the saved website.</p><h2 id="shared-links-and-clipboard" tabindex="-1">Shared Links and Clipboard <a class="header-anchor" href="#shared-links-and-clipboard" aria-label="Permalink to &quot;Shared Links and Clipboard&quot;">​</a></h2><p>On Android, Link Deck can receive text that you deliberately share from another app and use it to prepare a new bookmark. It can also read text from the clipboard when you choose the paste action and the platform permits access. Review shared or pasted content before saving it.</p><h2 id="backup-restore-import-and-export" tabindex="-1">Backup, Restore, Import, and Export <a class="header-anchor" href="#backup-restore-import-and-export" aria-label="Permalink to &quot;Backup, Restore, Import, and Export&quot;">​</a></h2><p>Complete backups contain profiles, folders, bookmarks, notes, tags, favourites, visit metadata, and settings. You can create a readable JSON backup or an encrypted <code>.linkdeck</code> backup. Encrypted backups use AES-256-GCM with a key derived from your passphrase using PBKDF2-SHA-256. The passphrase is not stored and cannot be recovered by the developer.</p><p>Browser-compatible HTML imports and exports are not encrypted. They can contain bookmark titles, URLs, favicons, timestamps, and folder structure. Files saved or shared outside Link Deck are handled by the destination you choose.</p><h2 id="information-collected-by-the-developer" tabindex="-1">Information Collected by the Developer <a class="header-anchor" href="#information-collected-by-the-developer" aria-label="Permalink to &quot;Information Collected by the Developer&quot;">​</a></h2><p>The developer does not receive bookmarks, browsing history, folders, notes, tags, PINs, backup passphrases, device identifiers, or usage telemetry. Link Deck does not sell user information.</p><p>If you email support, the developer receives only the information you choose to include and uses it to respond to your request. Do not email passwords, PINs, private bookmark collections, or backup files.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Depending on the features you use, Link Deck may use internet access for favicons, Google Fonts, and opening links; Android biometric authentication for optional unlock; file or document access for import, export, backup, and restore; and Android&#39;s share target for text you send to the app. The reviewed app does not require location, contacts, camera, microphone, phone, or SMS permissions.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>Link Deck data remains on the device until you delete bookmarks or profiles, clear app storage, or uninstall the app. Trashed bookmarks remain locally until they are permanently deleted or their containing profile is deleted.</p><p>Deleting app data does not remove backup or exported HTML files saved or shared outside Link Deck. Delete those copies separately from every destination. There is no developer-operated Link Deck account or cloud database to delete by email.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s Privacy&quot;">​</a></h2><p>Link Deck is not designed to collect children&#39;s personal information through a developer-operated service.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to This Policy&quot;">​</a></h2><p>This policy may be updated when Link Deck&#39;s features or data practices change. The dates above will be revised when an updated policy is published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',33))])}const v=i(l,[["render",p]]);export{y as __pageData,v as default};
